```kotlin
import kotlin.random.Random

class Minesweeper(private val height: Int, private val width: Int, private val numMines: Int) {

    private val minefield: Array<Array<Boolean>> = Array(height) { Array(width) { false } }
    private val gameboard: Array<Array<String>> = Array(height) { Array(width) { "-" } }

    private fun placeMines() {
        var minesToPlace = numMines
        while (minesToPlace > 0) {
            val row = Random.nextInt(height)
            val col = Random.nextInt(width)
            if (!minefield[row][col]) {
                minefield[row][col] = true
                minesToPlace--
            }
        }
    }

    private fun countAdjacentMines(row: Int, col: Int): Int {
        var count = 0
        for (r in row - 1..row + 1) {
            for (c in col - 1..col + 1) {
                if (r in 0 until height && c in 0 until width && minefield[r][c]) {
                    count++
                }
            }
        }
        return count
    }

    private fun revealCell(row: Int, col: Int) {
        if (minefield[row][col]) {
            gameboard[row][col] = "*"
        } else {
            val adjacentMines = countAdjacentMines(row, col)
            gameboard[row][col] = if (adjacentMines > 0) adjacentMines.toString() else "/"
            if (adjacentMines == 0) {
                for (r in row - 1..row + 1) {
                    for (c in col - 1..col + 1) {
                        if (r in 0 until height && c in 0 until width && gameboard[r][c] == "-") {
                            revealCell(r, c)
                        }
                    }
                }
            }
        }
    }

    fun play() {
        placeMines()

        var numRevealed = 0
        while (numRevealed < height * width - numMines) {
            println("Remaining mines: ${numMines - countMarkedMines()}")
            println("  " + (0 until width).joinToString(" "))
            for (row in 0 until height) {
                println("$row ${gameboard[row].joinToString(" ")}")
            }

            print("Enter row and column (e.g. 3 4): ")
            val input = readLine()!!.split(" ")
            val row = input[0].toInt()
            val col = input[1].toInt()

            if (minefield[row][col]) {
                gameboard[row][col] = "*"
                println("You lost!")
                return
            } else {
                revealCell(row, col)
                numRevealed = countRevealedCells()
            }
        }

        println("You won!")
    }

    private fun countRevealedCells(): Int {
        var count = 0
        for (row in 0 until height) {
            for (col in 0 until width) {
                if (gameboard[row][col] != "-") {
                    count++
                }
            }
        }
        return count
    }

    private fun countMarkedMines(): Int {
        var count = 0
        for (row in 0 until height) {
            for (col in 0 until width) {
                if (gameboard[row][col] == "X") {
                    count++
                }
            }
        }
        return count
    }
}

fun main() {
    println("Welcome to Minesweeper!")
    println("Enter the grid size and number of mines:")
    print("Height: ")
    val height = readLine()!!.toInt()
    print("Width: ")
    val width = readLine()!!.toInt()
    print("Number of mines: ")
    val numMines = readLine()!!.toInt()

    val game = Minesweeper(height, width, numMines)
    game.play()
}
